def _get_backend_versions():
    import netCDF4
    libnetcdf_version = netCDF4.__netcdf4libversion__
    if libnetcdf_version and '-development' in libnetcdf_version:
        libnetcdf_version = libnetcdf_version.replace('-development', '-dev')
    return {
        "netCDF4": Version(netCDF4.__version__),
        "libnetcdf": Version(libnetcdf_version),
        "xarray": Version(xr.__version__)
